values
  ('pattern-interrupt-first-frame', 'Pattern interrupt in the first frame', 'attention_psychology'::public.creative_rule_category, 'Open on a visual that breaks the rhythm viewers expect while scrolling: an unusual angle, an abrupt movement or an unexpected object.', 'Trigger an orienting response so the viewer pauses before deciding to scroll.',
   array['Short-form feeds where viewers decide in about a second', 'The topic itself is not instantly eye-catching']::text[], array['Calm, meditative content where a jolt would feel off-brand']::text[], 'Instead of a static talking head, the video opens with the creator dropping a stack of receipts onto the desk in close-up.',
   array['instagram_reel', 'talking_head', 'list_based', 'opinion', 'educational']::public.script_format[], '{}'::text[], array['meditative']::text[],
   null, 180, 'basic'::public.creative_complexity,
   'established_principle'::public.creative_evidence_type, 'Orienting response to novel stimuli is well documented (Sokolov); its effect on feed behaviour is an inference.', 'approved'::public.creative_rule_status, now()),
  ('motion-in-first-second', 'Movement within the first second', 'attention_psychology'::public.creative_rule_category, 'Ensure something moves in the first second — the camera, the subject or an on-screen element — rather than starting on a still image.', 'Avoid a frozen opening that reads as a static ad or thumbnail.',
