  ('face-and-eye-contact-early', 'Face and eye contact early', 'attention_psychology'::public.creative_rule_category, 'Show a human face looking into the lens within the first two seconds when a person is the messenger.', 'Use people''s strong attention to faces and direct gaze to create an immediate sense of being addressed.',
   array['Talking-head, opinion and educational formats', 'Personal brands']::text[], array['Faceless channels or product-only videos', 'Content where the subject''s identity must be protected']::text[], 'The creator looks straight into the camera and says the first line before cutting to b-roll.',
   array['talking_head', 'opinion', 'educational', 'instagram_reel']::public.script_format[], '{}'::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'established_principle'::public.creative_evidence_type, 'Preferential attention to faces and direct gaze is well established in perception research.', 'approved'::public.creative_rule_status, now()),
  ('salient-subject-contrast', 'Make the subject visually salient', 'attention_psychology'::public.creative_rule_category, 'Separate the main subject from the background through colour, light, focus or framing so the eye lands on it instantly.', 'Reduce the time a viewer needs to understand what the video is about.',
   array['Busy environments', 'Product shots']::text[], array['Intentional ensemble scenes where the environment is the subject']::text[], 'A red sneaker shot against a plain grey wall with shallow depth of field.',
   array['product_presentation', 'promotional', 'instagram_reel', 'tutorial']::public.script_format[], '{}'::text[], '{}'::text[],
   null, null, 'intermediate'::public.creative_complexity,
