   array['Community and engagement objectives']::text[], array['Engagement bait that platforms penalise (e.g., ‘comment YES if…’ with no purpose)']::text[], '“Which would you pick, A or B? Tell me why in one word.”',
   array['instagram_reel', 'opinion', 'talking_head']::public.script_format[], array['engage', 'community']::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'practitioner_heuristic'::public.creative_evidence_type, 'Check platform policies on engagement bait.', 'approved'::public.creative_rule_status, now()),
  ('save-for-later-cta', 'Save-for-later CTA', 'calls_to_action'::public.creative_rule_category, 'Ask viewers to save reference-style content they will need again.', 'Encourage a meaningful action for utility content.',
   array['Checklists, recipes, tutorials, lists']::text[], array['Entertainment pieces with no reuse value']::text[], '“Save this for your next grocery run.”',
   array['educational', 'tutorial', 'list_based', 'instagram_reel']::public.script_format[], array['educate']::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'practitioner_heuristic'::public.creative_evidence_type, null, 'approved'::public.creative_rule_status, now()),
  ('share-with-specific-person', 'Share with a specific person', 'calls_to_action'::public.creative_rule_category, 'Suggest sharing with a particular kind of person who would benefit.', 'Make sharing feel helpful and specific.',
   array['Relatable or useful content']::text[], array['Pressuring viewers to share']::text[], '“Send this to the friend who always forgets their passwords.”',
   array['instagram_reel', 'educational', 'storytelling', 'list_based']::public.script_format[], array['awareness', 'engage']::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'practitioner_heuristic'::public.creative_evidence_type, null, 'approved'::public.creative_rule_status, now()),
  ('soft-cta-trust-content', 'Soft CTA for trust-building content', 'calls_to_action'::public.creative_rule_category, 'Use a gentle invitation rather than a hard sell when the goal is trust or community.', 'Avoid undermining sincerity.',
   array['Personal stories, community content']::text[], array['Direct-response campaigns']::text[], '“If this helped, I share more of these on Sundays.”',
   array['storytelling', 'talking_head', 'narrative']::public.script_format[], array['trust', 'community']::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'practitioner_heuristic'::public.creative_evidence_type, null, 'approved'::public.creative_rule_status, now()),
  ('repeat-cta-in-caption', 'Repeat the CTA in the caption', 'calls_to_action'::public.creative_rule_category, 'Restate the CTA and any link instructions in the caption or pinned comment.', 'Support viewers who act after the video ends.',
   array['Any CTA involving a link or keyword']::text[], '{}'::text[], 'Caption ends with “Template → link in bio (free)”.',
   array['instagram_reel', 'educational', 'promotional', 'storytelling', 'talking_head', 'product_presentation', 'list_based', 'tutorial', 'opinion', 'narrative']::public.script_format[], '{}'::text[], '{}'::text[],
   null, null, 'basic'::public.creative_complexity,
   'practitioner_heuristic'::public.creative_evidence_type, null, 'approved'::public.creative_rule_status, now()),
  ('story-without-cta', 'Let some stories end without a CTA', 'calls_to_action'::public.creative_rule_category, 'For emotional or narrative pieces, consider ending on the story''s final beat with no explicit ask.', 'Preserve emotional impact; the CTA can live in the caption.',
   array['Narrative and emotional storytelling']::text[], array['Conversion campaigns', 'Videos whose objective requires an action']::text[], 'The documentary-style reel ends on the founder''s last line; the caption carries the link.',
   array['storytelling', 'narrative']::public.script_format[], array['trust', 'entertain', 'community']::text[], '{}'::text[],
   null, null, 'intermediate'::public.creative_complexity,
   'experimental'::public.creative_evidence_type, null, 'approved'::public.creative_rule_status, now())
on conflict (slug) where workspace_id is null do nothing;

